import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (int i = 0; i < n; i++) heap.add(sc.nextLong());
        // Huffman-style: always merge the two smallest values.
        long answer = 0;
        while (heap.size() > 1) {
            long total = heap.poll() + heap.poll();
            answer += total;
            heap.add(total);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	v := old[len(old)-1]
	*h = old[:len(old)-1]
	return v
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	h := make(minHeap, n)
	for i := range h {
		fmt.Fscan(in, &h[i])
	}
	heap.Init(&h)
	// Huffman-style: always merge the two smallest values.
	var answer int64
	for h.Len() > 1 {
		total := heap.Pop(&h).(int64) + heap.Pop(&h).(int64)
		answer += total
		heap.Push(&h, total)
	}
	fmt.Println(answer)
}
